你好，这是内嵌的 HTML 界面：
```html
<!DOCTYPE html>
<html>
<head><meta charset="utf-8"><style>body{font-family:sans-serif;padding:12px;background:#fdf6ec;color:#333}button{padding:8px 14px;margin:4px;border:none;border-radius:8px;background:#7c5cff;color:#fff}#out{margin-top:10px;padding:8px;background:#fff;border-radius:8px;border:1px solid #ddd}</style></head>
<body>
<h3>HTML 沙箱界面</h3>
<button onclick="bump()">计数 +1</button>
<button onclick="showMsgs()">最近消息数</button>

<button onclick="bumpRealm()">MVU 修为 +10</button>
<button onclick="showVars()">读 MVU 变量</button>
<div id="out">点击按钮试试</div>
<script>
function bump(){
  var raw = String(TavernHelper.getVar('count') || '');
  var n = parseInt(raw === '' ? '0' : raw, 10) + 1;
  TavernHelper.setVar('count', String(n));
  document.getElementById('out').textContent = '已计数 ' + n + ' 次（会话级持久变量）';
}
async function bumpRealm(){
  await TavernHelper.insertOrAssignVariables({主角状态: {修为: {进度百分比: 42, 当前境界: '筑基六层'}}});
  document.getElementById('out').textContent = '已写入 MVU 变量';
}
async function showVars(){
  var vars = await TavernHelper.getVariables();
  document.getElementById('out').textContent = 'MVU 变量: ' + JSON.stringify(vars);
}
async function showMsgs(){
  var msgs = await TavernHelper.getChatMessages(10);
  document.getElementById('out').textContent = '桥读到最近 ' + msgs.length + ' 条消息';
}
</script>
</body>
</html>
```
